python3 -I -c 'S="import sys,json,os,subprocess\nfrom pathlib import Path\nQ=lambda:\"python3 -I -c %cS=%s;exec(S)%c \\\"$@\\\"\\n\"%(39,json.dumps(S),39)\nv=sys.argv[1:]\nif v==[\"self\"]:print(Q(),end=\"\")\nelif v==[\"encode\"]:\n n=1\n for b in Q().encode():n=n*257+b+1\n print(hex(n)[2:])\nelif len(v)==2 and v[0]==\"decode\":\n n=int(v[1],16);a=[]\n while n>1:n,r=divmod(n-1,257);a.append(r)\n if n!=1:sys.exit(\"INVALID_G257\")\n sys.stdout.buffer.write(bytes(a[::-1]))\nelse:\n p=Path(os.getenv(\"UTO_MUSIC_HOME\",\".\"))/(\"voice.py\" if \"--voice\" in v or any(x.startswith(\"--voice=\") for x in v) else \"music.py\")\n if not p.is_file():sys.exit(\"Run from the repository directory or set UTO_MUSIC_HOME\")\n sys.exit(subprocess.call([sys.executable,str(p.resolve()),*v]))";exec(S)' "$@"
